const fs=require('fs');
function patch(path,apply){const before=fs.readFileSync(path,'utf8');const after=apply(before);if(after===before)throw new Error(`No change applied to ${path}`);fs.writeFileSync(path,after);}
patch('src/services/submissionRisk.js',s=>{const old=`  } else if (type === 'research') {\n    const doi = normalizedUrl(item.doi_url); const paper = normalizedUrl(item.paper_url);\n    if (doi) out.push(\`research-url:\${doi}\`);\n    if (paper) out.push(\`research-url:\${paper}\`);\n  } else if (type === 'internship') {`;const replacement=`  } else if (type === 'research') {\n    // Journal homepages are shared by many legitimate papers and are not unique evidence.\n    // Treat only paper-specific paths (or a real doi.org DOI) as duplicate evidence.\n    for (const value of [item.doi_url, item.paper_url]) {\n      const raw = text(value);\n      const normalized = normalizedUrl(raw);\n      if (!normalized) continue;\n      try {\n        const url = new URL(raw);\n        const pathParts = url.pathname.split('/').filter(Boolean);\n        const isDoi = /(^|\\.)doi\\.org$/i.test(url.hostname) && pathParts.length > 0;\n        if (isDoi || pathParts.length > 0) out.push(\`research-url:\${normalized}\`);\n      } catch (_) {}\n    }\n  } else if (type === 'internship') {`;if(!s.includes(old))throw new Error('research evidence block changed upstream');return s.replace(old,replacement);});
patch('src/routes/proofReview.js',s=>{const marker=`function storage() {\n    if (db.isLocal()) return null;\n    return db.supabaseClient()?.storage?.from('certificate-evidence') || null;\n}\n`;const helper=`${marker}\nasync function readR2Proof(path, env = globalThis.cloudflareEnv) {\n    const bucket = env?.CERTIFICATE_VAULT;\n    if (!path || !bucket?.get) return null;\n    const object = await bucket.get(path);\n    if (!object) return null;\n    const bytes = Buffer.from(await object.arrayBuffer());\n    return { bytes, mime: object.httpMetadata?.contentType || null, size: Number(object.size) || bytes.length };\n}\n`;if(!s.includes(marker))throw new Error('storage marker changed upstream');s=s.replace(marker,helper);const old=`        const evidenceStorage = storage();\n        if (!evidenceStorage) return res.status(503).json({ success: false, error: { code: 'VAULT_NOT_CONFIGURED', message: 'Proof storage is not configured.' } });\n        const entry = await db.selectOne(table, { id: req.params.id });`;const replacement=`        const evidenceStorage = storage();\n        const entry = await db.selectOne(table, { id: req.params.id });`;if(!s.includes(old))throw new Error('proof storage precheck changed upstream');s=s.replace(old,replacement);const scope=`        if (isObserver) {\n            const student = await studentForId(entry.student_id);\n            if (student?.branch !== req.observer.department) return res.status(403).json({ success: false, error: { code: 'OUT_OF_SCOPE', message: 'This entry belongs to another department.' } });\n        }\n\n`;const r2=`${scope}        // Current certificate uploads live in R2. Read R2 first, then fall back to legacy Supabase Storage.\n        try {\n            const r2Proof = await readR2Proof(entry.evidence_path);\n            if (r2Proof) {\n                res.setHeader('Content-Type', entry.evidence_mime || r2Proof.mime || 'application/octet-stream');\n                res.setHeader('Content-Length', String(r2Proof.size));\n                res.setHeader('Cache-Control', 'private, no-store, max-age=0');\n                res.setHeader('X-Content-Type-Options', 'nosniff');\n                res.setHeader('Content-Disposition', 'inline');\n                return res.end(r2Proof.bytes);\n            }\n        } catch (error) { console.error('R2 proof read failed, using legacy storage fallback:', error.message); }\n\n        if (!evidenceStorage) return res.status(503).json({ success: false, error: { code: 'VAULT_NOT_CONFIGURED', message: 'Proof storage is not configured.' } });\n\n`;if(!s.includes(scope))throw new Error('observer scope block changed upstream');s=s.replace(scope,r2);const eo=`module.exports = { admin: createRouter('admin'), observer: createRouter('observer'), normalizeStoredStatus, statusForDatabase, notifyVerifiedStudent, proofRedirectHtml };`;const en=`module.exports = { admin: createRouter('admin'), observer: createRouter('observer'), normalizeStoredStatus, statusForDatabase, notifyVerifiedStudent, proofRedirectHtml, readR2Proof };`;if(!s.includes(eo))throw new Error('proof exports changed upstream');return s.replace(eo,en);});
patch('public/js/student-experience-v1.js',s=>{const old=`  function storageKey(name, studentId = '') { return \`\${STORAGE_PREFIX}\${studentId}:\${name}\`; }\n  function muted() { return localStorage.getItem(storageKey('muted')) === '1' || reduceMotion(); }\n  function setMuted(value) { localStorage.setItem(storageKey('muted'), value ? '1' : '0'); renderMuteToggle(); }`;const replacement=`  function storageKey(name, studentId = '') { return \`\${STORAGE_PREFIX}\${studentId}:\${name}\`; }\n  function userMuted() { return localStorage.getItem(storageKey('muted')) === '1'; }\n  function muted() { return userMuted(); }\n  function setMuted(value, button = null) { localStorage.setItem(storageKey('muted'), value ? '1' : '0'); renderMuteToggle(button); }`;if(!s.includes(old))throw new Error('mute state block changed upstream');s=s.replace(old,replacement);s=s.replace(`  function haptic(kind = 'soft') {\n    if (muted() || !navigator.vibrate) return;`,`  function haptic(kind = 'soft') {\n    if (muted() || reduceMotion() || !navigator.vibrate) return;`);const ro=`  function renderMuteToggle() {\n    if (!document.body.classList.contains('student-dashboard-page')) return;\n    const nav = document.querySelector('.navbar-inner > div:last-child');\n    if (!nav) return;\n    let button = document.getElementById('experienceMuteToggle');`;const rn=`  function renderMuteToggle(existingButton = null) {\n    if (!document.body.classList.contains('student-dashboard-page')) return;\n    const nav = document.querySelector('.navbar-inner > div:last-child');\n    if (!nav) return;\n    let button = existingButton || document.getElementById('experienceMuteToggle');`;if(!s.includes(ro))throw new Error('mute renderer changed upstream');s=s.replace(ro,rn);const co=`      button.addEventListener('click', () => setMuted(!muted()));`;const cn=`      button.addEventListener('click', () => { const next = !userMuted(); setMuted(next, button); });`;if(!s.includes(co))throw new Error('mute click changed upstream');s=s.replace(co,cn);s=s.replace(`    const isMuted = muted();`,`    const isMuted = userMuted();`);return s;});
patch('test/anti-cheat-duplicate-impersonation-v3.test.js',s=>{const a=`test('research exact repeated evidence URL is a high-confidence duplicate', () => {`;const add=`test('same journal and same collaborators with different paper titles are not duplicates', () => {\n  const shared = { publication:'IJVRA - International Journal of Versatile Research and Analysis', authors:'Dr.Nitin Santosh Patil, Dr.Sandip Niranjan Vende, Mr.Ketan V.Patil', paper_url:'https://www.ijvra.org/' };\n  const first = { id:'a', title:'Multi-Angle Industrial Inspection Fusion: A Unified Deep Learning Framework for Viewpoint-Invariant Defect Detection', ...shared };\n  const second = { id:'b', title:'A Different Industrial Inspection Research Paper', ...shared };\n  assert.deepEqual([...duplicateIds('research',[first,second])], []);\n  assert.equal(submissionFingerprints('research',first).some(v => v === 'research-url:https://www.ijvra.org'), false);\n});\n\n`;if(!s.includes(a))throw new Error('anti-cheat anchor changed upstream');return s.replace(a,add+a);});
patch('test/proof-review-layout.test.js',s=>{const env=`process.env.NODE_ENV='test';\nprocess.env.SUPABASE_URL='';\nprocess.env.SUPABASE_KEY='';\nprocess.env.JWT_SECRET=process.env.JWT_SECRET||'test-secret-at-least-thirty-two-characters';\n\n`;if(!s.startsWith("process.env.NODE_ENV='test';"))s=env+s;return s+`\ntest('proof viewing reads current R2 evidence before legacy Supabase fallback', async () => {\n  const { readR2Proof } = require('../src/routes/proofReview');\n  const bytes = Uint8Array.from([1,2,3,4]);\n  const proof = await readR2Proof('certificates/student/proof.jpg', { CERTIFICATE_VAULT:{ get: async () => ({ size:4, httpMetadata:{contentType:'image/jpeg'}, arrayBuffer:async()=>bytes.buffer }) } });\n  assert.equal(proof.mime, 'image/jpeg');\n  assert.equal(proof.size, 4);\n  assert.deepEqual([...proof.bytes], [1,2,3,4]);\n  const route = read('src/routes/proofReview.js');\n  assert.ok(route.indexOf('readR2Proof(entry.evidence_path)') < route.indexOf('createSignedUrl(entry.evidence_path, 120)'));\n});\n`;});
